INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (115489,3,0,'It couldn\'t have been helped, you know. We tried to alter it, but it was all part of a larger scheme.',12,0,100.0,1,0,78200,124016,0,'LegionCore');
